# Nutritionix Nutrition Analysis
import requests

NUTRITIONIX_APP_ID = "79dcp2841e6tndjjbn1373bq1tv0p3ud"
NUTRITIONIX_API_KEY = "your_api_key"
BASE_URL = "https://trackapi.nutritionix.com/v2"

def analyze_recipe(ingredients):
    """Analyze nutrition for list of ingredients"""
    response = requests.post(
        f"{BASE_URL}/natural/nutrients",
        headers={
            "x-app-id": NUTRITIONIX_APP_ID,
            "x-app-key": NUTRITIONIX_API_KEY,
            "Content-Type": "application/json"
        },
        json={"query": "\n".join(ingredients)}
    )
    return response.json()

def get_food_details(food_name):
    """Get detailed food information"""
    response = requests.post(
        f"{BASE_URL}/search/instant",
        headers={
            "x-app-id": NUTRITIONIX_APP_ID,
            "x-app-key": NUTRITIONIX_API_KEY
        },
        params={"query": food_name}
    )
    return response.json()
